  var RULES = null;
  function rules() {
    if (RULES) return RULES;
    var set = Object.create(null);
    Object.keys(DATA).forEach(function (tld) {
      DATA[tld].split(' ').forEach(function (left) {
        if (left) set[left + '.' + tld] = 1;      // "co.in", "*.ck", "!www.ck", ...
      });
    });
    RULES = set;
    return set;
  }

  function normalizeHost(host) {
    if (typeof host !== 'string') return '';
    var h = host.trim().toLowerCase().replace(/\.+$/, '');
    if (!h) return '';
    if (/[^\x00-\x7f]/.test(h)) {                  // IDN -> punycode, as the rules are stored
      try { h = new URL('http://' + h).hostname; } catch (e) { return ''; }
    }
    return h;
  }

  function isIPLiteral(h) {
    return /^\d{1,3}(\.\d{1,3}){3}$/.test(h) || h.indexOf(':') !== -1 || /^\[.*\]$/.test(h);
  }

  // Returns the public suffix of a hostname ("co.in" for "sbi.co.in"), or '' if invalid.
  function publicSuffix(host) {
    var h = normalizeHost(host);
    if (!h || isIPLiteral(h)) return '';
    var labels = h.split('.');
    if (labels.some(function (l) { return !l; })) return '';
    var R = rules();
    var i, cand, rest;

    // 1. exception rules win over everything (suffix = rule minus its leftmost label)
    for (i = 0; i < labels.length; i++) {
      cand = labels.slice(i).join('.');
      if (R['!' + cand]) return labels.slice(i + 1).join('.');
    }
    // 2. otherwise the matching rule with the most labels (exact or wildcard) prevails
    for (i = 0; i < labels.length; i++) {
      cand = labels.slice(i).join('.');
      if (R[cand]) return cand;
      rest = labels.slice(i + 1).join('.');
      if (rest && R['*.' + rest]) return cand;
    }
    // 3. default rule "*": the last label is the suffix
    return labels[labels.length - 1];
  }

